#!/usr/bin/env python3
"""Run from project root: python3 fix_ui.py"""
import base64, os, sys

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "app/page.tsx": "",
    "app/layout.tsx": "",
    "components/TerminalArena.tsx": "",
    "components/PortfolioTab.tsx": "",
    "components/LanguageSelector.tsx": "",
    "components/CompactWallet.tsx": "",
    "components/AuthOptions.tsx": "",
    "components/SessionProvider.tsx": "",
    "app/auth/signin/page.tsx": "",
    "app/auth/verify/page.tsx": "",
}

for path, enc in FILES.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print(f"WRITTEN  {path}")

print("\nAll UI files written. Run:")
print("  npm run build && git add -A && git commit -m \"feat: wire all UI — auth, language, wallet, studio visible\" && git push origin main")
